# -*- coding: utf-8 -*-
"""Generate a standalone interactive view from the project business data."""
from pathlib import Path
import json

base = Path(__file__).resolve().parents[1]
data = {k: json.loads((base / 'data' / (k+'.json')).read_text()) for k in ('pages','topics','keywords','competitors','graph')}
data['baseline'] = json.loads((base/'growth-board/kpi-snapshots/2026-10-21.json').read_text())
data['inventory'] = json.loads((base/'data/inventory.json').read_text()) if (base/'data/inventory.json').exists() else []
data['topic_candidates'] = json.loads((base/'data/topic-candidates.json').read_text()) if (base/'data/topic-candidates.json').exists() else []
implementation = base.parent/'2026-10-21-全站规划落实/execution-state.json'
data['implementation'] = json.loads(implementation.read_text()) if implementation.exists() else None
review_dir=base.parent/'2026-10-21-全站规划落实/reviews'
ownership=base.parent/'2026-10-21-全站规划落实/ownership/topic-owners.json'
data['topic_ownership']=json.loads(ownership.read_text())['decisions'] if ownership.exists() else []
dispositions=base.parent/'2026-10-21-全站规划落实/ownership/article-dispositions.json'
data['article_dispositions']=json.loads(dispositions.read_text())['decisions'] if dispositions.exists() else []
data['article_reviews']=[]
for file in sorted(review_dir.glob('batch-*.json')):
    data['article_reviews'].extend(json.loads(file.read_text())['rows'])
